// Builds public/passages-of-the-day.js from scripts/passages-of-the-day.list and the bundled BSB corpus.
// Usage: bun scripts/build-passages.mjs [--check]   (--check fails if the generated file is stale)
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { LIBRARY_BOOKS } from '../public/library-data.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const out = join(root, 'public/passages-of-the-day.js');
const ALIASES = { psalm: 19 };
const byName = new Map(LIBRARY_BOOKS.map(book => [book.name.toLowerCase(), book.n]));

const verses = new Map();
for (const line of readFileSync(join(root, 'public/data/corpus.txt'), 'utf8').split('\n')) {
  const [b, c, v, ...rest] = line.split('\t');
  if (rest.length) verses.set(`${b}.${c}.${v}`, rest.join('\t'));
}

const entries = [], problems = [];
for (const raw of readFileSync(join(root, 'scripts/passages-of-the-day.list'), 'utf8').split('\n')) {
  const line = raw.trim();
  if (!line || line.startsWith('#')) continue;
  const match = line.match(/^(.+?)\s+(\d+):(\d+)(?:-(\d+))?$/);
  if (!match) { problems.push(`Cannot read the address "${line}"`); continue; }
  const [, name, chapter, start, end = start] = match;
  const book = ALIASES[name.toLowerCase()] || byName.get(name.toLowerCase());
  if (!book) { problems.push(`Unknown book in "${line}"`); continue; }
  if (Number(end) - Number(start) < 1 || Number(end) - Number(start) > 14) { problems.push(`"${line}" must be 2 to 15 verses`); continue; }
  const text = [];
  for (let v = Number(start); v <= Number(end); v++) {
    const verse = verses.get(`${book}.${chapter}.${v}`);
    if (!verse) { problems.push(`"${line}" is not in the corpus (verse ${v})`); break; }
    text.push(verse.trim());
  }
  if (text.length === Number(end) - Number(start) + 1) entries.push([book, Number(chapter), Number(start), Number(end)]);
}
const seen = new Set();
for (const e of entries) { const key = e.slice(0, 4).join('.'); if (seen.has(key)) problems.push(`duplicate ${key}`); seen.add(key); }
if (entries.length < 365) problems.push(`only ${entries.length} passages; at least 365 are needed`);
if (problems.length) { console.error(problems.join('\n')); process.exit(1); }

// Deal the list out in a fixed, evenly spread order: step through it by a stride coprime to its length, so consecutive days
// come from different parts of the Bible. The same list always gives the same order.
const gcd = (a, b) => b ? gcd(b, a % b) : a;
let stride = Math.round(entries.length * 0.382);
while (gcd(stride, entries.length) !== 1) stride++;
const ordered = entries.map((_, i) => entries[(i * stride) % entries.length]);

const body = `// Generated by scripts/build-passages.mjs from scripts/passages-of-the-day.list, checking every verse exists in the bundled BSB text. Do not edit by hand.
// [book number, chapter, first verse, last verse]; the text is read from the Bible when opened
export const PASSAGES = ${JSON.stringify(ordered, null, 0).replace(/\],\[/g, '],\n  [').replace(/^\[\[/, '[\n  [').replace(/\]\]$/, ']\n]')};
`;
if (process.argv.includes('--check')) {
  if (!existsSync(out) || readFileSync(out, 'utf8') !== body) { console.error('build-passages: public/passages-of-the-day.js is stale; run bun scripts/build-passages.mjs'); process.exit(1); }
} else { writeFileSync(out, body); console.log(`built public/passages-of-the-day.js (${entries.length} passages, stride ${stride})`); }
